def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    bars = []
    for r in (0, h - 1):
        cols = [c for c, v in enumerate(grid[r]) if v != bg]
        if cols:
            bars.append((r, min(cols), max(cols), grid[r][cols[0]]))
    if not bars:
        return out

    bar_color = bars[0][3]
    ray_colors = [v for v in counts if v != bg and v != bar_color]
    if not ray_colors:
        return out
    ray_color = ray_colors[0]

    # Dots select matching positions within the two edge bars.
    active = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == ray_color:
                for _, left, right, _ in bars:
                    if left <= c <= right:
                        active.add(c - left)
    if not active:
        active = set(range(min(right - left for _, left, right, _ in bars) + 1))

    for r, left, right, _ in bars:
        step = 1 if r == 0 else -1
        for i in active:
            c = left + i
            if c > right:
                continue
            rr = r + step
            while 0 <= rr < h:
                v = grid[rr][c]
                if v == ray_color:
                    out[rr][c] = 4
                    break
                if v != bg:
                    break
                out[rr][c] = ray_color
                rr += step

    return out
